//! Independent 100-digit geometry of sediment-reduced culvert sections at frozen depths.
//!
//! Depths run up from the bed. Each value holds the round-down and round-up binary64 bits of
//! the exact quantity, in `QUANTITIES` order. `relative_width` holds the frozen width
//! allowance of each quantity, relative to it.

// Generated by `transcribe.py` in `resource/evidence/culvert-blockage/` from its frozen
// `sections.json`. Regenerate instead of editing.

/// SHA256 of the frozen `sections.json`.
pub const SECTIONS_SHA256: &str =
    "7e63173d02e2501eb7b1adf9ffeb99129724818e0da93d088b57c1862df7a0b2";

/// Quantity names in row order.
pub const QUANTITIES: [&str; 7] = [
    "area",
    "top_width",
    "wall_perimeter",
    "perimeter",
    "weighted_perimeter",
    "radius",
    "moment",
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Shape {
    Circular,
    Box,
    HorizontalEllipse,
    VerticalEllipse,
    PipeArch,
    Arch,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    Dry,
    Free,
    Full,
}

/// One evidence section: the barrel inputs in constructor order, the bed and the ratio.
#[derive(Clone, Copy, Debug)]
pub struct Section {
    pub name: &'static str,
    pub shape: Shape,
    pub inputs: &'static [u64],
    pub sediment_depth: u64,
    pub reduced_rise: u64,
    pub bed_manning: u64,
    pub wall_manning: u64,
    pub roughness_ratio: u64,
    pub bed_band: &'static str,
}

/// One section value with bounds, its power of the reduced rise and its relative width.
#[derive(Clone, Copy, Debug)]
pub struct Value {
    pub section: usize,
    pub name: &'static str,
    pub bounds: [u64; 2],
    pub power: i32,
    pub relative_width: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct Row {
    pub section: usize,
    pub fraction: &'static str,
    pub depth: u64,
    pub state: State,
    pub values: [[u64; 2]; 7],
    pub relative_width: [f64; 7],
}

